/**
 * `agent-sdk mcp` — stdio ↔ streamable-HTTP proxy for an agent's MCP endpoint.
 *
 * Every served agent is an MCP server at `<base>/v1/mcp`. MCP clients that
 * spawn stdio servers (Cursor, Claude Code, …) can reach it through this
 * command: newline-delimited JSON-RPC on stdin/stdout, one POST per message
 * to `--url <baseUrl>` (a local `serve` mount or a self-hosted base URL), with
 * optional `--bearer-token`.
 *
 * `agent-sdk mcp install --url <baseUrl>` writes the matching entry into
 * `~/.cursor/mcp.json` so the agent shows up as an MCP server in Cursor:
 *
 *   { "mcpServers": { "weather-agent": {
 *       "command": "agent-sdk",
 *       "args": ["mcp", "--url", "http://127.0.0.1:3000/weather-agent"] } } }
 *
 * Hosted architecture v2 deployments have no user-reachable MCP endpoint yet,
 * so `--prod` is a usage error.
 *
 * stdout is reserved for the MCP wire in serve mode; all logging goes to
 * stderr.
 */
import { readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
import { CLI_COMMAND_NAME as CLI, LOG_PREFIX } from "./distribution.js";
import { writePrivateFile } from "./private-file.js";
import { sleep as defaultSleep } from "./sleep.js";
import { isRecord } from "./is-record.js";
/** Mount path of the MCP surface relative to an agent base URL. */
const MCP_PATH = "/v1/mcp";
/**
 * Upper bound per POST. The remote endpoint bounds `ask`/`check` waits at
 * ~55s, so a healthy turn always responds well inside this; past it the
 * engine is unreachable or hung.
 */
const REQUEST_TIMEOUT_MS = 120_000;
/** Attempts per message (initial + retries after backoff). */
const FORWARD_ATTEMPTS = 3;
/**
 * Statuses that cannot have reached the agent's tool logic, so retrying
 * cannot double-run a turn: proxy-unreachable errors (502/503/504). A plain
 * 500 is ambiguous and is surfaced to the client instead.
 */
const RETRYABLE_STATUSES = new Set([502, 503, 504]);
/** Hosted v2 deployments have no user-reachable MCP endpoint yet. */
const PROD_UNSUPPORTED = "--prod is not available: hosted v2 deployments have no MCP endpoint for the CLI yet. " +
    "Pass --url <baseUrl> for a running server.";
export async function cmdMcp(subcommand, options) {
    const err = options.err ?? defaultErr;
    if (subcommand === undefined) {
        return cmdMcpServe(options);
    }
    if (subcommand === "install") {
        return cmdMcpInstall(options);
    }
    if (subcommand === "oauth") {
        const connection = options.oauthConnection;
        if (connection === undefined || connection.trim() === "") {
            err(`Usage: ${CLI} mcp oauth <connection> [--dir .] [--store] [--slug <slug>] [--team <id>]\n` +
                `Authorize defineConnection({ url, oauth: true }) (host PKCE).\n` +
                `--store upserts MCP_OAUTH_<NAME>_* secrets on the hosted deployment.\n`);
            return 1;
        }
        const { cmdMcpOauth } = await import("./cli-mcp-oauth.js");
        return cmdMcpOauth({
            dir: options.dir,
            connection,
            store: options.store,
            dryRun: options.dryRun,
            slug: options.slug,
            team: options.team,
            apiKey: options.apiKey,
        });
    }
    err(`Unknown mcp subcommand "${subcommand}".\n` +
        `Usage: ${CLI} mcp [install|oauth <connection>] --url <baseUrl>\n`);
    return 1;
}
// ============================================================================
// serve mode: stdio ↔ /v1/mcp
// ============================================================================
export async function cmdMcpServe(options) {
    const err = options.err ?? defaultErr;
    if (options.prod === true) {
        err(`${PROD_UNSUPPORTED}\n`);
        return 2;
    }
    if (options.url === undefined) {
        err(`${CLI} mcp requires --url <baseUrl>\n`);
        return 1;
    }
    const base = normalizeBaseUrl(options.url);
    if (typeof base !== "string") {
        err(`${base.error}\n`);
        return 1;
    }
    const target = staticTarget(base, options.bearerToken);
    err(`${LOG_PREFIX} mcp: proxying stdio <-> ${target.mcpUrl}\n`);
    const stdin = options.stdin ?? process.stdin;
    const stdout = options.stdout ?? process.stdout;
    const fetchImpl = options.fetchImpl ?? fetch;
    const sleep = options.sleep ?? defaultSleep;
    const pending = new Set();
    const handleLine = async (line) => {
        const outcome = await forwardMessage({ target, fetchImpl, sleep, line });
        if (outcome.kind === "empty") {
            return;
        }
        if (outcome.kind === "json") {
            writeWireBody(stdout, outcome.body, line, err);
            return;
        }
        emitFailure(stdout, line, outcome.message, err);
    };
    await new Promise((done) => {
        let buffer = "";
        const enqueueLine = (raw) => {
            const line = raw.trim();
            if (line === "") {
                return;
            }
            const task = handleLine(line)
                .catch((error) => {
                err(`${LOG_PREFIX} mcp: ${describeError(error)}\n`);
            })
                .finally(() => {
                pending.delete(task);
            });
            pending.add(task);
        };
        const onChunk = (chunk) => {
            buffer += typeof chunk === "string" ? chunk : chunk.toString("utf8");
            let newline = buffer.indexOf("\n");
            while (newline !== -1) {
                const line = buffer.slice(0, newline);
                buffer = buffer.slice(newline + 1);
                newline = buffer.indexOf("\n");
                enqueueLine(line);
            }
        };
        let finished = false;
        const finish = () => {
            if (finished) {
                return;
            }
            finished = true;
            enqueueLine(buffer);
            buffer = "";
            done();
        };
        stdin.on("data", onChunk);
        stdin.once("end", finish);
        stdin.once("close", finish);
        stdin.once("error", finish);
    });
    // Drain in-flight turns so piped one-shot usage still sees its replies.
    await Promise.allSettled([...pending]);
    return 0;
}
function staticTarget(baseUrl, bearerToken) {
    const headers = {};
    if (bearerToken !== undefined && bearerToken.trim() !== "") {
        headers.authorization = `Bearer ${bearerToken.trim()}`;
    }
    return { mcpUrl: joinMcpPath(baseUrl), headers };
}
async function forwardMessage(args) {
    const { target, fetchImpl, sleep, line } = args;
    let lastFailure = "request failed";
    for (let attempt = 0; attempt < FORWARD_ATTEMPTS; attempt++) {
        if (attempt > 0) {
            await sleep(500 * attempt);
        }
        let response;
        try {
            response = await fetchImpl(target.mcpUrl, {
                method: "POST",
                headers: {
                    ...target.headers,
                    "content-type": "application/json",
                    // The streamable-HTTP server transport 406s unless the client
                    // accepts both, even in JSON response mode.
                    accept: "application/json, text/event-stream",
                },
                body: line,
                signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
            });
        }
        catch (error) {
            if (isTimeoutError(error)) {
                // The turn may have started; retrying could double-send it.
                return {
                    kind: "failed",
                    message: `no response within ${REQUEST_TIMEOUT_MS / 1000}s (the agent may still be processing; check its sessions)`,
                };
            }
            lastFailure = `request failed: ${describeError(error)}`;
            continue;
        }
        if (response.status === 202) {
            // Notification/response-only message: nothing to relay.
            await response.text().catch(() => "");
            return { kind: "empty" };
        }
        const text = await response.text().catch(() => "");
        if (response.ok) {
            if (text.trim() === "") {
                return { kind: "empty" };
            }
            return { kind: "json", body: text };
        }
        lastFailure = `upstream HTTP ${response.status}${text.trim() === "" ? "" : `: ${truncateForLog(text)}`}`;
        if (RETRYABLE_STATUSES.has(response.status)) {
            continue;
        }
        return { kind: "failed", message: lastFailure };
    }
    return { kind: "failed", message: lastFailure };
}
/**
 * Relay an upstream JSON body onto the stdio wire. The body is re-serialized
 * so output is always one message per line, and batch responses are split
 * into individual lines (the stdio transport has no batch framing).
 */
function writeWireBody(stdout, body, inboundLine, err) {
    let parsed;
    try {
        parsed = JSON.parse(body);
    }
    catch {
        emitFailure(stdout, inboundLine, `upstream returned a non-JSON payload: ${truncateForLog(body)}`, err);
        return;
    }
    const messages = Array.isArray(parsed) ? parsed : [parsed];
    for (const message of messages) {
        stdout.write(`${JSON.stringify(message)}\n`);
    }
}
/**
 * Answer every request id in the inbound message with a JSON-RPC error so
 * the client fails the call instead of hanging on a lost response.
 * Notification-only failures are stderr-logged.
 */
function emitFailure(stdout, inboundLine, message, err) {
    err(`${LOG_PREFIX} mcp: ${message}\n`);
    for (const id of requestIdsOf(inboundLine)) {
        stdout.write(`${JSON.stringify({
            jsonrpc: "2.0",
            id,
            error: { code: -32000, message },
        })}\n`);
    }
}
/** Ids of JSON-RPC *requests* (has `method` + `id`) in a raw wire line. */
function requestIdsOf(line) {
    let parsed;
    try {
        parsed = JSON.parse(line);
    }
    catch {
        return [];
    }
    const messages = Array.isArray(parsed) ? parsed : [parsed];
    const ids = [];
    for (const message of messages) {
        if (message !== null && typeof message === "object" && "method" in message && "id" in message) {
            const id = isRecord(message) ? message.id : undefined;
            if (typeof id === "string" || typeof id === "number") {
                ids.push(id);
            }
        }
    }
    return ids;
}
export async function cmdMcpInstall(options) {
    const err = options.err ?? defaultErr;
    const stdout = options.stdout ?? process.stdout;
    if (options.prod === true || options.remote === true) {
        err(`${PROD_UNSUPPORTED}\n`);
        return 2;
    }
    if (options.url === undefined) {
        err(`${CLI} mcp install requires --url <baseUrl>\n`);
        return 1;
    }
    const base = normalizeBaseUrl(options.url);
    if (typeof base !== "string") {
        err(`${base.error}\n`);
        return 1;
    }
    const derived = options.name ?? deriveNameFromUrl(base);
    if (derived === undefined) {
        err(`Could not derive a server name from ${base}; pass --name <serverName>.\n`);
        return 1;
    }
    const name = resolveServerName(derived, derived);
    const args = ["mcp", "--url", base];
    if (options.bearerToken !== undefined && options.bearerToken !== "") {
        args.push("--bearer-token", options.bearerToken);
        err("note: --bearer-token is written to mcp.json in plain text\n");
    }
    const entry = { command: CLI, args };
    if (options.print === true) {
        stdout.write(`${JSON.stringify({ mcpServers: { [name]: entry } }, null, 2)}\n`);
        return 0;
    }
    const path = cursorMcpJsonPath();
    try {
        await upsertMcpJsonEntry(path, name, entry);
    }
    catch (error) {
        err(`${describeError(error)}\n`);
        return 1;
    }
    if (options.json === true) {
        stdout.write(`${JSON.stringify({ ok: true, path, name, entry })}\n`);
        return 0;
    }
    stdout.write(`Installed MCP server "${name}" in ${path}\n` +
        `  ${entry.command} ${entry.args.join(" ")}\n` +
        "Cursor watches this file; the server appears without a restart.\n");
    return 0;
}
/** `~/.cursor/mcp.json` — the user-level Cursor MCP config. */
export function cursorMcpJsonPath(home = process.env.HOME ?? homedir()) {
    const resolved = home.trim() === "" ? homedir() : home;
    return join(resolved, ".cursor", "mcp.json");
}
async function upsertMcpJsonEntry(path, name, entry) {
    let root = {};
    let raw;
    try {
        raw = await readFile(path, "utf8");
    }
    catch {
        raw = undefined;
    }
    if (raw !== undefined && raw.trim() !== "") {
        let parsed;
        try {
            parsed = JSON.parse(raw);
        }
        catch (error) {
            throw new Error(`${path} is not valid JSON (${describeError(error)}); fix it and re-run.`);
        }
        if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
            throw new Error(`${path} must contain a JSON object; fix it and re-run.`);
        }
        if (!isRecord(parsed)) {
            throw new Error(`${path} must contain a JSON object; fix it and re-run.`);
        }
        root = parsed;
    }
    const existing = root.mcpServers;
    const servers = isRecord(existing) ? existing : {};
    servers[name] = entry;
    root.mcpServers = servers;
    await writePrivateFile(path, `${JSON.stringify(root, null, 2)}\n`);
}
function resolveServerName(name, fallback) {
    const trimmed = name?.trim();
    if (trimmed !== undefined && trimmed !== "") {
        return trimmed;
    }
    return fallback;
}
/** Last path segment of the agent base URL (the mount slug), if any. */
function deriveNameFromUrl(baseUrl) {
    const segments = new URL(baseUrl).pathname.split("/").filter((s) => s !== "");
    const last = segments.at(-1);
    if (last === undefined || last === "") {
        return undefined;
    }
    return last;
}
// ============================================================================
// Shared helpers
// ============================================================================
/** Agent base URL → MCP endpoint URL (idempotent when already pointed at it). */
export function joinMcpPath(baseUrl) {
    const parsed = new URL(baseUrl);
    let pathname = parsed.pathname.replace(/\/+$/, "");
    if (!pathname.endsWith(MCP_PATH)) {
        pathname = `${pathname}${MCP_PATH}`;
    }
    parsed.pathname = pathname;
    return parsed.toString();
}
function normalizeBaseUrl(raw) {
    let parsed;
    try {
        parsed = new URL(raw);
    }
    catch {
        return { error: `invalid --url: ${raw}` };
    }
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
        return { error: `unsupported --url protocol: ${parsed.protocol}` };
    }
    return raw.replace(/\/+$/, "");
}
function isTimeoutError(error) {
    return error instanceof Error && (error.name === "TimeoutError" || error.name === "AbortError");
}
function truncateForLog(text) {
    const flat = text.replace(/\s+/g, " ").trim();
    return flat.length > 300 ? `${flat.slice(0, 300)}…` : flat;
}
function describeError(error) {
    if (error instanceof Error) {
        const cause = error.cause instanceof Error && error.cause.message !== "" ? ` (${error.cause.message})` : "";
        return `${error.message}${cause}`;
    }
    return String(error);
}
function defaultErr(text) {
    process.stderr.write(text);
}
